import java.util.Scanner;

public class Main {
    static int[][] dp;
    static int n, h;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextInt();
        h = scanner.nextInt();

        dp = new int[n + 1][n + 1];

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 && j == 0) {
                    dp[i][j] = 1;
                } else if (i == 0 || j == 0) {
                    dp[i][j] = 0;
                } else {
                    dp[i][j] = -1;
                }
            }
        }

        // Compute dp for all states
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                t(i, j);
            }
        }

        int result = 0;
        for (int i = h; i <= n; i++) {
            result += dp[n][i];
        }
        System.out.println(result);
        scanner.close();
    }

    static int t(int n, int h) {
        if (dp[n][h] == -1) {
            int sum = 0;
            for (int m = 1; m <= n; m++) {
                int sum1 = 0;
                for (int i = 0; i < h; i++) {
                    sum1 += t(n - m, i);
                }
                int sum2 = 0;
                for (int i = 0; i < h - 1; i++) {
                    sum2 += t(m - 1, i);
                }
                sum += t(m - 1, h - 1) * sum1 + t(n - m, h - 1) * sum2;
            }
            dp[n][h] = sum;
        }
        return dp[n][h];
    }
}
